```go
package erratum

import "errors"

func Use(opener ResourceOpener, input string) error {
	var resource Resource
	var err error
	for {
		resource, err = opener()
		if err == nil {
			break
		}
		var te TransientError
		if !errors.As(err, &te) {
			return err
		}
	}
	defer resource.Close()
	func() {
		defer func() {
			if r := recover(); r != nil {
				if fe, ok := r.(FrobError); ok {
					resource.Defrob(fe.defrobTag)
				}
				err = r.(error)
			}
		}()
		resource.Frob(input)
	}()
	return err
}
```

Wait — the recover's r could be a FrobError (which implements error), or it could be an error like errors.New("meh") (which implements error). But what if the panic value isn't an error? The spec says "panic with FrobError (or some other kind of error)". The tests only panic with errors. But to be safe, handle the case where r isn't an error — convert it to fmt.Errorf("%v", r). Keep it simple yet robust.

